package emoji

import (
	"strconv"
	"strings"
)

const (
	CatalogHeader = "# name\tgroup\tsubgroup\tuse_count\n" +
		"# Generated by tools/emojigen. Do not edit by hand.\n"
	TypesHeader = "# type\tname\tcount\n" +
		"# Generated by tools/emojigen. Do not edit by hand.\n"
)

func FormatTable(header string, rows [][]string) string {
	var buf strings.Builder
	buf.WriteString(header)
	for _, row := range rows {
		buf.WriteString(strings.Join(row, "\t"))
		buf.WriteByte('\n')
	}
	return buf.String()
}

func CatalogRow(name, group, subgroup string, useCount int) []string {
	return []string{name, group, subgroup, strconv.Itoa(useCount)}
}

func TypesRow(commitType, name string, count int) []string {
	return []string{commitType, name, strconv.Itoa(count)}
}
